CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '', oab_number text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('lawyer','client')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; REVOKE INSERT,UPDATE,DELETE ON public.user_roles FROM authenticated,anon;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_legal_role(who uuid, wanted text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=who AND role=wanted); $$;
REVOKE ALL ON FUNCTION public.has_legal_role(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_legal_role(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.create_legal_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'client'); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_legal_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER legal_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_legal_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,coalesce(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'client' FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.calendar_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, client_id uuid, process_id uuid REFERENCES public.legal_process_records(id), title text NOT NULL, kind text NOT NULL CHECK(kind IN ('deadline','hearing','meeting','call')), starts_at timestamptz NOT NULL, responsible text NOT NULL, location text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.calendar_records TO authenticated; GRANT ALL ON public.calendar_records TO service_role;
ALTER TABLE public.calendar_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs DROP CONSTRAINT audit_logs_entity_type_check;
ALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_entity_type_check CHECK(entity_type IN ('process','document','permission','calendar'));
CREATE OR REPLACE FUNCTION public.capture_legal_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE old_row jsonb; new_row jsonb; row_data jsonb; actor uuid; fields text[]; actor_name text; BEGIN IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF; IF TG_OP<>'INSERT' THEN old_row:=to_jsonb(OLD); END IF; IF TG_OP<>'DELETE' THEN new_row:=to_jsonb(NEW); END IF; row_data:=coalesce(new_row,old_row); actor:=auth.uid(); SELECT nullif(display_name,'') INTO actor_name FROM public.profiles WHERE id=actor; SELECT coalesce(array_agg(k ORDER BY k),'{}') INTO fields FROM jsonb_object_keys(row_data) k WHERE (old_row->k) IS DISTINCT FROM (new_row->k); INSERT INTO public.audit_logs(owner_id,actor_id,actor_label,entity_type,entity_id,action,before_data,after_data,changed_fields) VALUES((row_data->>'owner_id')::uuid,actor,coalesce(actor_name,actor::text,'Sistema / operação administrativa'),TG_ARGV[0],(row_data->>'id')::uuid,CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'UPDATE' THEN 'update' ELSE 'delete' END,old_row-'reviewed_items',new_row-'reviewed_items',fields); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_calendar AFTER INSERT OR UPDATE OR DELETE ON public.calendar_records FOR EACH ROW EXECUTE FUNCTION public.capture_legal_audit('calendar');
ALTER TABLE public.legal_document_records ADD COLUMN reviewed_items jsonb NOT NULL DEFAULT '[]';
ALTER TABLE public.legal_document_records ADD COLUMN reviewed_at timestamptz;
ALTER TABLE public.legal_document_records ADD COLUMN reviewer_id uuid;
CREATE POLICY shared_process_read ON public.legal_process_records FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.resource_permissions r WHERE r.resource_type='process' AND r.resource_id=legal_process_records.id AND r.grantee_id=auth.uid()));
CREATE POLICY permission_recipient_read ON public.resource_permissions FOR SELECT TO authenticated USING(grantee_id=auth.uid());
CREATE POLICY shared_document_read ON public.legal_document_records FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.resource_permissions r WHERE r.resource_type='document' AND r.resource_id=legal_document_records.id AND r.grantee_id=auth.uid()));
CREATE POLICY calendar_read ON public.calendar_records FOR SELECT TO authenticated USING(owner_id=auth.uid() OR client_id=auth.uid());
CREATE POLICY calendar_insert ON public.calendar_records FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND public.has_legal_role(auth.uid(),'lawyer') AND (process_id IS NULL OR EXISTS(SELECT 1 FROM public.legal_process_records p WHERE p.id=process_id AND p.owner_id=auth.uid())) AND (client_id IS NULL OR EXISTS(SELECT 1 FROM public.resource_permissions r WHERE r.resource_type='process' AND r.resource_id=process_id AND r.owner_id=auth.uid() AND r.grantee_id=client_id)));
CREATE POLICY calendar_update ON public.calendar_records FOR UPDATE TO authenticated USING(owner_id=auth.uid() AND public.has_legal_role(auth.uid(),'lawyer')) WITH CHECK(owner_id=auth.uid() AND (process_id IS NULL OR EXISTS(SELECT 1 FROM public.legal_process_records p WHERE p.id=process_id AND p.owner_id=auth.uid())) AND (client_id IS NULL OR EXISTS(SELECT 1 FROM public.resource_permissions r WHERE r.resource_type='process' AND r.resource_id=process_id AND r.owner_id=auth.uid() AND r.grantee_id=client_id)));
CREATE POLICY calendar_delete ON public.calendar_records FOR DELETE TO authenticated USING(owner_id=auth.uid() AND public.has_legal_role(auth.uid(),'lawyer'));
CREATE POLICY process_lawyer_only ON public.legal_process_records AS RESTRICTIVE FOR ALL TO authenticated USING(public.has_legal_role(auth.uid(),'lawyer') OR EXISTS(SELECT 1 FROM public.resource_permissions r WHERE r.resource_type='process' AND r.resource_id=legal_process_records.id AND r.grantee_id=auth.uid())) WITH CHECK(owner_id=auth.uid() AND public.has_legal_role(auth.uid(),'lawyer'));
CREATE POLICY document_lawyer_only ON public.legal_document_records AS RESTRICTIVE FOR ALL TO authenticated USING(public.has_legal_role(auth.uid(),'lawyer') OR EXISTS(SELECT 1 FROM public.resource_permissions r WHERE r.resource_type='document' AND r.resource_id=legal_document_records.id AND r.grantee_id=auth.uid())) WITH CHECK(owner_id=auth.uid() AND public.has_legal_role(auth.uid(),'lawyer'));
CREATE POLICY permissions_lawyer_only ON public.resource_permissions AS RESTRICTIVE FOR ALL TO authenticated USING(public.has_legal_role(auth.uid(),'lawyer') OR grantee_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND public.has_legal_role(auth.uid(),'lawyer'));
COMMENT ON TABLE public.resource_permissions IS 'Explicit audited read access for recipients; roles are assigned only by trusted administration.';
CREATE INDEX calendar_owner_date ON public.calendar_records(owner_id,starts_at); CREATE INDEX calendar_client_date ON public.calendar_records(client_id,starts_at);